INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (62, 355, 'PE Shopping bags', '../upload/image/20181227/20181227134057_41610.jpg', '<p>PE Shopping bags</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (62, 354, 'PE CLING FILM (FOOD WRAPPING)', '../upload/image/20181227/20181227132254_83341.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;">PE CLING FILM (FOOD WRAPPING)</span></p> <p><span style="color:#009900;font-family:Verdana;">The product does not contain any plasticizer. It features transparency, tensile strong, very good anti-fog performance. It is ideal for food packaging materials. </span></p> <p><span style="color:#009900;font-family:Verdana;">Thickness :8-15UM</span></p> <p><span style="color:#009900;font-family:Verdana;">Width :300MM,350MM,450MM,500MM</span></p> <p><span style="color:#009900;font-family:Verdana;">Length :30M,50M,60M,100M,120M,150M,200M,500,1500M</span></p> <p><span style="color:#009900;font-family:Verdana;">Inner core:1.5”,1.8”,2”,3”,6”</span></p> <p><span style="color:#009900;font-family:Verdana;">Applications: packaging vegetables, fruit, cooked food. Applies to refrigerators, microwave ovens.</span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (62, 353, 'PE pallet wrapping film- hand use and machine use', '../upload/image/20181227/20181227131644_31088.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;font-size:16px;">PE Stretch Film for pallets package</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Blown PE Stretch Film for pallets pallet package, it characteristics excellent anti-piercing and stretching ability. Lightweight, strong tenacity, excellent puncture resistance, good self-adhesion</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Thickness: 15 – 20UM ( Microns) for hand-warp , 15-25 UM ( Microns) for machine-warp</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Width: 50-750MM</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Grade: hand use, semi-automatic machine use, auto-machine use </span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Color: natural color(clear), black, blue, red, ivory-white </span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"><img alt="" src="../upload/image/20181227/20181227131730_61064.jpg"/><img alt="" src="../upload/image/20181227/20181227131748_27619.jpg"/></span></p>', '2026-09-06 20:58:45');
