INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (62, 179, 'PVC PE food cling wrapping film', '../upload/image/20181226/20181226162009_58224.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;">PVC PE food cling wrapping film</span></p> <p><span style="color:#009900;font-family:Verdana;">1. PVC food grade film or PVC cling film which were used for food packing in super market or other things packing. </span><br/> <span style="color:#009900;font-family:Verdana;"> Thickness of PVC cling film: 8 9 10 11 12 microns. </span><br/> <span style="color:#009900;font-family:Verdana;"> Width of PVC cling film: 180-1500MM </span><br/> <span style="color:#009900;font-family:Verdana;"> Length of PVC cling film: 300,500,800,1000,1500M or others. </span><br/> <span style="color:#009900;font-family:Verdana;"> Applications of PVC cling film: packing food or others. </span><br/> <span style="color:#009900;font-family:Verdana;"> packing of PVC cling film: cartons and pallets, per roll per carton</span><br/> <span style="color:#009900;font-family:Verdana;"> Types of PVC film: center fold or single. </span><br/> <span style="color:#009900;font-family:Verdana;"> 2. PE cling film in jumbo rolls and Smaller rolls for supermarket</span><br/> <span style="color:#009900;font-family:Verdana;"> Thickness of PE cling film: 8 9 10 11 12 microns. </span><br/> <span style="color:#009900;font-family:Verdana;"> Width of PE cling film: 180-1500MM </span><br/> <span style="color:#009900;font-family:Verdana;"> PVC cling film, PVC film, PVC food wrapping film, PVC shrink film</span><br/> <span style="color:#009900;font-family:Verdana;"> 3. PE (polyethylene)Stretch Film for pallets package</span><br/> <span style="color:#009900;font-family:Verdana;"> Thickness (Um)* Width (mm)* Length (m) Kg/ roll Roll / Box </span><br/> <span style="color:#009900;font-family:Verdana;"> 1 15*500*300(3''inner core &amp; 1.5'' inner core)2.06 4/6/8rolls/Box</span><br/> <span style="color:#009900;font-family:Verdana;"> 2 17*500*300(3''inner core &amp; 1.5'' inner core)2.34 4/6/8rolls/Box </span><br/> <span style="color:#009900;font-family:Verdana;"> 3 20*500*300(3''inner core &amp; 1.5'' inner core)2.75 4/6/8rolls/Box </span><br/> <span style="color:#009900;font-family:Verdana;"> Customer''s own requirement is available for us such as printed OEM logos and private label or particular size and package style.</span></p>', '2026-09-06 20:58:45');